CREATE TABLE q(k INT, v INT);
INSERT INTO q VALUES (2, 2), (2, 0), (3, 1);
CREATE TABLE t(k INT);
INSERT INTO t VALUES (1), (2);
WITH c AS (SELECT k FROM q), d AS (SELECT k FROM c) SELECT c.k FROM c WHERE (SELECT count(*) FROM d) = 3;
WITH c AS (SELECT k, v FROM q), d AS (SELECT k FROM c) SELECT c.k, c.v FROM c WHERE c.k IN (SELECT k FROM d) AND c.v = 0;
WITH c AS (SELECT k FROM q), d AS (SELECT k FROM c) SELECT t.k FROM t WHERE (SELECT count(*) FROM c WHERE (SELECT max(k) FROM d WHERE d.k >= t.k) = 3) = 3;
WITH RECURSIVE c(k) AS (SELECT 0 UNION ALL SELECT k + 1 FROM c WHERE k < 3), d AS (SELECT k FROM c) SELECT c.k FROM c WHERE (SELECT count(*) FROM d) = 4;
WITH RECURSIVE c(k) AS (SELECT 0 UNION ALL SELECT k + 1 FROM c WHERE k < 3), d AS (SELECT k FROM c) SELECT t.k FROM t WHERE (SELECT count(*) FROM c AS x WHERE (SELECT max(k) FROM d) = 3) = 4;
WITH RECURSIVE c(k) AS (SELECT 1 UNION ALL SELECT t.k + c.k FROM c JOIN t ON t.k = c.k WHERE c.k < 5), d AS (SELECT k FROM c) SELECT c.k FROM c WHERE EXISTS (SELECT 1 FROM d WHERE d.k >= c.k);
WITH RECURSIVE c(k) AS (SELECT 0 UNION ALL SELECT k + 1 FROM c WHERE k < 3), d AS (SELECT k FROM c) SELECT a.k, b.k FROM t AS a LEFT JOIN c AS b ON b.k IN (SELECT k FROM d WHERE d.k > a.k);
WITH RECURSIVE c(k) AS (SELECT 0 UNION ALL SELECT k + 1 FROM c WHERE k < 3), d AS (SELECT k FROM c), f AS (SELECT k FROM d UNION SELECT k + 10 FROM c) SELECT c.k FROM c WHERE c.k IN (SELECT k FROM f) AND EXISTS (SELECT 1 FROM d WHERE d.k = c.k);
